<?php use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Porównanie wersji · '.$page['title']; ?>
<div class="page-head"><div><p class="eyebrow">Historia</p><h1>v<?=Html::e($old['version_no'])?> ↔ v<?=Html::e($new['version_no'])?></h1><p><?=Html::e($page['title'])?></p></div><a class="button secondary" href="<?=Html::e(Url::to('/pages/'.$page['id'].'/history'))?>">Historia</a></div>
<section class="card"><dl class="system-list"><dt>Tytuł v<?=Html::e($old['version_no'])?></dt><dd><?=Html::e($old['title'])?></dd><dt>Tytuł v<?=Html::e($new['version_no'])?></dt><dd><?=Html::e($new['title'])?></dd><dt>Autor v<?=Html::e($old['version_no'])?></dt><dd><?=Html::e($old['author_name']??$old['author_username']??'—')?></dd><dt>Autor v<?=Html::e($new['version_no'])?></dt><dd><?=Html::e($new['author_name']??$new['author_username']??'—')?></dd><dt>Daty</dt><dd><?=Html::e($old['created_at'])?> → <?=Html::e($new['created_at'])?></dd></dl></section>
<section class="card diff-view" aria-label="Różnice treści"><?php foreach($diff as $line):?><div class="diff-line diff-<?=Html::e($line['type'])?>"><span class="diff-marker"><?=$line['type']==='add'?'+':($line['type']==='remove'?'-':' ')?></span><code><?=Html::e($line['text'])?></code></div><?php endforeach;?></section>

<?php if($propertyChanges):?><section class="card section-card"><h2>Zmiany właściwości</h2><div class="table-scroll"><table><thead><tr><th>Właściwość</th><th>Przed</th><th>Po</th></tr></thead><tbody><?php foreach($propertyChanges as $change):?><tr><td><?=Html::e($change['new']['label']??$change['old']['label']??$change['key'])?></td><td><?=Html::e($change['old']['value']??'—')?></td><td><?=Html::e($change['new']['value']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
